import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  texture, uv, positionLocal, normalLocal, uniform, vec3, float,
  smoothstep, mix
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const T = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color,
    AmbientLight, DirectionalLight, SRGBColorSpace } = T;

  const group = new Group();
  group.name = config.id ? String(config.id) : 'pricing-row';

  // visual spec colors (fall back to named defaults)
  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };
  const cInk     = new Color(colors.ink);
  const cSurface = new Color(colors.surface);
  const cPaper   = new Color(colors.paper);
  const cAccent  = new Color(colors.accent);

  const vec3From = (col) => vec3(float(col.r), float(col.g), float(col.b));

  // ---- inner wrapper (entrance settle + primitives operate here) ----
  const inner = new Group();
  group.add(inner);

  const ROW_W = 4.2;
  const ROW_H = 0.7;

  // ---- backdrop gradient panel (dark, never void) ----
  const backPlane = new PlaneGeometry(ROW_W + 0.25, ROW_H + 0.18);
  const backMat = new MeshBasicNodeMaterial();
  backMat.colorNode = mix(
    vec3From(cSurface),
    vec3From(cInk),
    smoothstep(float(0), float(1), uv().y.mul(float(-1)).add(float(1)))
  );
  backMat.transparent = true;
  backMat.opacityNode = float(0.95);
  const back = new Mesh(backPlane, backMat);
  back.position.set(0, 0, -0.18);
  inner.add(back);

  // ---- parallax / displaced plane (hero subject) ----
  const dispStrength = uniform(0.06);
  const planeGeo = new PlaneGeometry(ROW_W, ROW_H, 96, 96);
  const mat = new MeshStandardNodeMaterial({
    roughness: 0.55,
    metalness: 0.5,
    transparent: true,
    opacity: 0.98
  });
  // base gradient before texture loads
  mat.colorNode = mix(
    vec3From(cSurface),
    vec3From(cInk),
    smoothstep(float(0), float(1), uv().y.mul(float(-1)).add(float(1)))
  );
  // default (no depth) displacement so positionNode is stable
  mat.positionNode = positionLocal.add(normalLocal.mul(dispStrength));

  const plane = new Mesh(planeGeo, mat);
  plane.position.set(0, 0, 0);
  inner.add(plane);

  // ---- accent divider line (subtle) ----
  const divGeo = new BoxGeometry(ROW_W - 0.35, 0.012, 0.01);
  const divMat = new MeshStandardNodeMaterial({
    color: cAccent,
    emissive: cAccent,
    emissiveIntensity: 0.95,
    roughness: 0.5,
    metalness: 0.45
  });
  const divider = new Mesh(divGeo, divMat);
  divider.position.set(0.05, -ROW_H / 2 - 0.06, 0.02);
  inner.add(divider);

  // small accent dot (left rail) — single accent on <=10% of frame
  const dotGeo = new PlaneGeometry(0.09, 0.09);
  const dotMat = new MeshStandardNodeMaterial({
    color: cAccent,
    emissive: cAccent,
    emissiveIntensity: 1.15,
    roughness: 0.45
  });
  const dot = new Mesh(dotGeo, dotMat);
  dot.position.set(-ROW_W / 2 + 0.14, 0, 0.03);
  inner.add(dot);

  // ---- contact shadow plane (grounded read) ----
  const shadowGeo = new PlaneGeometry(ROW_W * 1.05, ROW_H * 1.25);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0.55 });
  shadowMat.colorNode = vec3(float(0), float(0), float(0));
  shadowMat.opacityNode = smoothstep(float(0.5), float(0), uv().y.mul(float(-1)).add(float(0.5))).mul(float(0.55));
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -ROW_H / 2 - 0.02, -0.1);
  inner.add(shadow);

  // ---- node-local lighting (key + accent rim + ambient fill) ----
  const ambient = new AmbientLight(cPaper, 0.6);
  inner.add(ambient);

  const key = new DirectionalLight(0xffffff, 1.0);
  key.position.set(-2.2, 1.8, 2.4);
  inner.add(key);

  const rim = new DirectionalLight(cAccent, 0.75);
  rim.position.set(2.6, 0.9, 2.0);
  inner.add(rim);

  // ---- text content (spec says none — render nothing, do not invent) ----
  const textItems = config.textContent ?? config?.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    /* spec declares no text content for this row */
  }

  // ---- async asset attach ----
  let loadedImageTex = null;
  let loadedDepthTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      try { tex.colorSpace = SRGBColorSpace; } catch (_) {}
      loadedImageTex = tex;
      mat.colorNode = texture(tex, uv());
      mat.needsUpdate = true;
    }).catch(() => {});
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((dTex) => {
      loadedDepthTex = dTex;
      mat.positionNode = positionLocal.add(
        normalLocal.mul(texture(dTex, uv()).r.mul(dispStrength))
      );
      mat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- cinematic primitives ----
  const primHandles = [];
  for (const prim of (config.cinematicPrimitives ?? [])) {
    if (!ctx.primitives || !ctx.primitives[prim.name]) continue;
    try {
      const r = ctx.primitives[prim.name](inner, prim.params ?? {});
      if (r) primHandles.push(r);
    } catch (_) {}
  }

  // ---- entrance (weighted-settle) ----
  const tl = gsap.timeline();
  inner.position.y = 0.4;
  inner.scale.set(0.96, 0.96, 0.96);
  inner.materialOpacity = 0;
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  tl.to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0);
  tl.fromTo(inner, { materialOpacity: 0 }, { materialOpacity: 1, duration: 0.5, ease: 'power2.out' }, 0);

  // ---- interaction handlers ----
  const hoverTween = { target: null };

  const triggerHoverIn = () => {
    if (hoverTween.target) hoverTween.target.kill();
    hoverTween.target = gsap.to(inner.position, {
      y: 0.15, duration: 0.32, ease: 'power3.out'
    });
  };
  const triggerHoverOut = () => {
    if (hoverTween.target) hoverTween.target.kill();
    hoverTween.target = gsap.to(inner.position, {
      y: 0, duration: 0.4, ease: 'power3.out'
    });
  };
  const triggerClick = () => {
    gsap.fromTo(inner.scale,
      { x: 0.97, y: 0.97, z: 0.97 },
      { x: 1, y: 1, z: 1, duration: 0.45, ease: 'back.out(2)' }
    );
    try { ctx.emit('hub-pricing.select', { id: config.id ?? null }); } catch (_) {}
    // data binding descriptor: trpc.visits.book.slot -> confirmPanel
    try { ctx.emit('pricing-row.select', { binding: 'trpc.visits.book.slot', target: 'confirmPanel' }); } catch (_) {}
  };

  group.userData.handlers = {
    onPointerEnter: triggerHoverIn,
    onPointerLeave: triggerHoverOut,
    onClick: triggerClick
  };

  // expose binding metadata for the adapter
  group.userData.bindings = config.dataBindings ?? [];

  // ---- cleanup ----
  group.userData.cleanup = () => {
    tl.kill();
    if (hoverTween.target) hoverTween.target.kill();
    for (const h of primHandles) { try { h.cleanup && h.cleanup(); } catch (_) {} try { h.timeline && h.timeline.kill && h.timeline.kill(); } catch (_) {} }
    planeGeo.dispose(); backPlane.dispose(); divGeo.dispose();
    dotGeo.dispose(); shadowGeo.dispose();
    mat.dispose(); backMat.dispose(); divMat.dispose(); dotMat.dispose(); shadowMat.dispose();
    if (loadedImageTex && loadedImageTex.dispose) loadedImageTex.dispose();
    if (loadedDepthTex && loadedDepthTex.dispose) loadedDepthTex.dispose();
  };

  return group;
}
